def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract individual groups of nested parentheses
    groups = []
    current_group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
        elif char == ")":
            open_count -= 1

        current_group += char

        if open_count == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced and non-nested
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return len(stack) == 0

    # Step 4: Return a list of balanced and non-nested groups as separate strings
    return [group for group in groups if is_balanced(group)]

